# Python 3 program to validate 
# IPv4 address 

import re

def validate_char(s):
    """Function to check if the ip address validate valid characters"""
    pattern = re.compile(r'[@_!#$%^&*()<>?/\|}{~:]')
    if(pattern.search(s) == None):
        return True
    else:
        return False

def validate_octet(s):
    """Function to check for the wildcard"""
    if s == "*":
        return True
    if s == "-":
        return True
    if not s.isdigit() or int(s) > 255:
        return False
    return True

def validate_IPv4(s): 
    """Function to validate a given IPv4 address"""
    l = s.split(".")

    if not validate_char(s):
        return False
    if len(l) != 4: 
        return False
    for x in l: 
        if not validate_octet(x):
            return False
    return True

# Driver Code 
s = "192.168.*.-"
if validate_IPv4(s): 
    print("valid") 
else: 
    print("Invalid")
```

In the given code I have added support for special characters and wildcards through `validate_char` and `validate_octet` method respectively. In `validate_char` method, regular expression is used to check if an invalid special character is present in the IP address. In `validate_octet` method, it is checked whether the given octets are valid, i.e., a digit within 0-255, and '*' and '-' are wildcards. Now, the code can handle special characters and wildcards in the IP address.

